### Step 3: SwissEph position orchestration in `src/calc.rs`

Add `SwephPositions` struct and `sweph_positions()` function. This is the SwissEph equivalent of Moshier's `compute_pipeline` — it orchestrates all the body evaluations needed for the correction pipeline:

```rust
use crate::sweph_file::{SwissEphFile, evaluate_body, body_file_id, find_file_for_jd};
use crate::sweph_file::types::{SEI_FLG_HELIO, SEI_MOON};

struct SwephPositions {
    planet_bary: [f64; 6],
    earth_bary: [f64; 6],
    earth_helio: [f64; 6],
    sun_bary: [f64; 6],
}

const SEI_SUNBARY: i32 = 10;

fn sweph_positions(
    planet_file: &SwissEphFile,
    moon_file: &SwissEphFile,
    body_id: i32,
    jd: f64,
    need_speed: bool,
) -> Result<SwephPositions, Error> {
    let n = if need_speed { 6 } else { 3 };

    // EMB (body 0) — barycentric equatorial J2000
    let (emb, _) = evaluate_body(planet_file, 0, jd, need_speed)?;
    // Moon (body 1) — geocentric equatorial J2000
    let (moon_geo, _) = evaluate_body(moon_file, SEI_MOON, jd, need_speed)?;

    // Earth = EMB - Moon/(EARTH_MOON_MRAT + 1)
    let mut earth_bary = [0.0; 6];
    for i in 0..n { earth_bary[i] = emb[i] - moon_geo[i] / (EARTH_MOON_MRAT + 1.0); }

    // Barycentric Sun: body 10 has EMBHEL → heliocentric Earth
    // C approximation: sun_bary = emb - helio_earth
    let (helio_earth, _) = evaluate_body(planet_file, SEI_SUNBARY, jd, need_speed)?;
    let mut sun_bary = [0.0; 6];
    for i in 0..n { sun_bary[i] = emb[i] - helio_earth[i]; }

    // Earth heliocentric (for deflection geometry)
    let mut earth_helio = [0.0; 6];
    for i in 0..n { earth_helio[i] = earth_bary[i] - sun_bary[i]; }

    // Target planet
    let (mut planet, _) = evaluate_body(planet_file, body_id, jd, need_speed)?;
    // Heliocentric → barycentric if SEI_FLG_HELIO (Mercury, Venus)
    if let Some(pd) = planet_file.planet_data(body_id) {
        if pd.iflg & SEI_FLG_HELIO != 0 {
            for i in 0..n { planet[i] += sun_bary[i]; }
        }
    }

    Ok(SwephPositions { planet_bary: planet, earth_bary, earth_helio, sun_bary })
}
```

### Step 4: `calc_planet_sweph` in `src/calc.rs`

SwissEph planet calculation with niter=1 light-time. Key differences from Moshier `calc_planet`:
- Two-pass light-time loop (`for j in 0..=1`)
- Re-evaluate planet at retarded time via `evaluate_body`
- Velocity from Chebyshev derivative (analytic)
- Speed correction uses barycentric coordinates
- Aberration Earth velocity correction: re-evaluate Earth at retarded time from SE1 files

```rust
pub fn calc_planet_sweph(
    jd: f64, body: Body,
    planet_files: &[SwissEphFile], moon_files: &[SwissEphFile],
    flags: CalcFlags, models: &AstroModels,
) -> Result<([f64; 24], CalcFlags), Error> {
    let body_id = body_file_id(body).ok_or(...)?;
    let need_speed = flags.contains(CalcFlags::SPEED);

    let planet_file = find_file_for_jd(planet_files, body_id, jd)
        .ok_or(Error::BeyondEphemerisLimits { ... })?;
    let moon_file = find_file_for_jd(moon_files, SEI_MOON, jd)
        .ok_or(Error::BeyondEphemerisLimits { ... })?;

    let pos = sweph_positions(planet_file, moon_file, body_id, jd, need_speed)?;

    // Geocentric
    let mut xx = [0.0; 6];
    for i in 0..6 { xx[i] = pos.planet_bary[i] - pos.earth_bary[i]; }

    // Light-time (niter=1: two-pass loop)
    let mut dt = 0.0;
    if !flags.contains(CalcFlags::TRUEPOS) {
        // Speed correction setup: geo position at t-1 day
        let mut xxsp = [xx[0] - xx[3], xx[1] - xx[4], xx[2] - xx[5]];
        let xxsv_sp = xxsp;
        let xxsv = [pos.planet_bary[0], pos.planet_bary[1], pos.planet_bary[2]];

        // Two-pass light-time loop (j=0,1 for niter=1)
        for _ in 0..=1 {
            let dist = (xx[0]*xx[0] + xx[1]*xx[1] + xx[2]*xx[2]).sqrt();
            dt = dist * AUNIT / CLIGHT / 86400.0;
            for i in 0..3 {
                xx[i] = xxsv[i] - dt * pos.planet_bary[i+3] - pos.earth_bary[i];
            }
        }
        // Speed correction loop (same niter)
        let mut dt_sp = 0.0;
        for _ in 0..=1 {
            let sp_geo = [xxsp[0] - pos.earth_bary[0], xxsp[1] - pos.earth_bary[1],
                          xxsp[2] - pos.earth_bary[2]];
            let dist_sp = (sp_geo[0]*sp_geo[0]+sp_geo[1]*sp_geo[1]+sp_geo[2]*sp_geo[2]).sqrt();
            dt_sp = dist_sp * AUNIT / CLIGHT / 86400.0;
            for i in 0..3 { xxsp[i] = xxsv_sp[i] - dt_sp * pos.planet_bary[i+3]; }
        }

        // Re-evaluate planet at retarded time
        let (mut retarded, _) = evaluate_body(planet_file, body_id, jd - dt, need_speed)?;
        if let Some(pd) = planet_file.planet_data(body_id) {
            if pd.iflg & SEI_FLG_HELIO != 0 {
                for i in 0..6 { retarded[i] += pos.sun_bary[i]; }
            }
        }

        // Geocentric from re-evaluated position
        for i in 0..6 { xx[i] = retarded[i] - pos.earth_bary[i]; }

        // Speed correction
        if need_speed {
            for i in 0..3 { xx[i+3] -= (dt - dt_sp) * retarded[i+3]; }
            // Note: xxsp subtraction pattern from C ref needs careful implementation
        }
    }

    if !need_speed { xx[3] = 0.0; xx[4] = 0.0; xx[5] = 0.0; }

    // Deflection (planet heliocentric at retarded time for geometry)
    if !flags.contains(CalcFlags::TRUEPOS) && !flags.contains(CalcFlags::NOGDEFL) {
        let mut planet_helio_ret = [0.0; 6];
        for i in 0..3 {
            planet_helio_ret[i] = xx[i] + pos.earth_helio[i];
            planet_helio_ret[i+3] = pos.planet_bary[i+3];
        }
        deflect_light(&mut xx, &pos.earth_helio, &planet_helio_ret, need_speed);
    }

    // Aberration (earth_bary velocity for SwissEph, matching C)
    if !flags.contains(CalcFlags::TRUEPOS) && !flags.contains(CalcFlags::NOABERR) {
        aberr_light(&mut xx, &[pos.earth_bary[3], pos.earth_bary[4], pos.earth_bary[5]], need_speed);
        // Earth velocity correction at retarded time
        if need_speed {
            // Re-derive Earth at jd-dt from SE1 files
            let pos_ret = sweph_positions(planet_file, moon_file, body_id, jd - dt, true)?;
            for i in 0..3 {
                xx[i+3] += pos.earth_bary[i+3] - pos_ret.earth_bary[i+3];
            }
        }
    }

    if !need_speed { xx[3] = 0.0; xx[4] = 0.0; xx[5] = 0.0; }

    // Frame bias, precession, app_pos_rest (identical to Moshier)
    if !flags.contains(CalcFlags::ICRS) {
        frame_bias(&mut xx, jd, flags, models, FrameTransform::GcrsToJ2000);
    }
    let (eps, nut_val, nutv) = precess_and_ephem(&mut xx, jd, flags, models);
    Ok((app_pos_rest(&mut xx, flags, &eps, &nut_val, nutv.as_ref()), flags))
}
```

**Note**: The exact speed correction pattern (xxsp subtraction) needs careful matching against the C code during implementation — the C ref doc's summary is ambiguous. I'll instrument and compare if golden tests don't match on first pass.

